using GameTranslator.Core;
namespace GameTranslator.Translation.Tests;
public class DialogueReadingRegressionTests {
 private sealed class Reader(params string[] text):ITextReader {private readonly Queue<string> rows=new(text);public string Read(Frame image)=>rows.Count>0?rows.Dequeue():"";}
 private sealed class Translator:ITextTranslator {public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously);public TaskCompletionSource Release=new(TaskCreationOptions.RunContinuationsAsynchronously);public bool Hold;public int Calls;public async Task<string> TranslateAsync(string text,CancellationToken cancellationToken=default){Calls++;Started.TrySetResult();if(Hold)await Release.Task.WaitAsync(cancellationToken);return "ينبغي أن نواصل السير.";}}
 private sealed class BoxReader(Reading reading):ITextReader {public string Read(Frame image)=>reading.Text;public Reading ReadLines(Frame image,bool deep)=>reading;}
 private sealed class CaptureTranslator:ITextTranslator {public string? Source;public Task<string> TranslateAsync(string text,CancellationToken token=default){Source=text;return Task.FromResult("حوار عربي كامل من سطرين.");}}
 [Fact]public async Task RecoveryKeepsBothWrappedLinesEvenWhenOcrBoxesHaveAGap(){
  var reader=new BoxReader(new Reading([new("We need to leave",new(.2,.1,.8,.2)),new("before they find us.",new(.2,.55,.8,.65))]));
  var translator=new CaptureTranslator();var sender=new Sender();var pipeline=new SubtitlePipeline(reader,translator,sender);
  DialogueReadingPolicy.Configure(pipeline,true,"dialogue");await pipeline.ProcessAsync(Frame.Blank(64,64),new(.7,.97,.12,.78));await pipeline.WaitForTranslationsAsync();
  Assert.Equal("We need to leave\nbefore they find us.",translator.Source);Assert.Single(sender.Lines);Assert.False(pipeline.CleanFastPathOnly);Assert.False(pipeline.DialogueBlockOnly);
 }
 private sealed class Sender:ISubtitleSender {public List<string> Lines=[];public void SendSubtitle(string text,int durationMs=15000,TextBox? box=null,bool paragraphs=false,bool replaces=false)=>Lines.Add(text);public void Clear(){}}
 [Fact]public void MapControlsDoNotEnterSpokenDialogue(){var r=DialogueProfile.DialogueOnly(Reading.FromText("SET DI\nREMOVE 01\nLeave me alone!"),new(0,0,1,1),"GTA6");Assert.Equal("Leave me alone!",r.Text);}
 [Fact]public void VehicleStatisticsCannotBeJoinedToSpokenDialogue(){var r=DialogueProfile.DialogueOnly(Reading.FromText("SPEED\nACCELERATION\nSTRENGTH\nRATING\nYou know how it goes."),new(0,0,1,1),"GTA6");Assert.Equal("You know how it goes.",r.Text);Assert.Equal("Speed",DialogueProfile.DialogueOnly(Reading.FromText("Speed"),new(0,0,1,1),"GTA6").Text);}
 [Fact]public async Task LocalDialogueStartsOnCompleteFirstReadWithoutNewForcedDelay(){var sender=new Sender();var translator=new Translator();var pipeline=new SubtitlePipeline(new Reader("We should keep moving."),translator,sender);DialogueReadingPolicy.Configure(pipeline,true,"dialogue");await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));await pipeline.WaitForTranslationsAsync();Assert.Single(sender.Lines);Assert.Equal(1,translator.Calls);}
 [Fact]public async Task SlightlyLateResultSurvivesAnOcrGap(){long time=0;var sender=new Sender();var translator=new Translator{Hold=true};var pipeline=new SubtitlePipeline(new Reader("We should keep moving.","",""),translator,sender,scheduler:ReadScheduler.Always(),clock:()=>time);DialogueReadingPolicy.Configure(pipeline,true,"dialogue");await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));await translator.Started.Task.WaitAsync(TimeSpan.FromSeconds(3));time=100;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));time=1000;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));time=1150;translator.Release.TrySetResult();await pipeline.WaitForTranslationsAsync();Assert.Single(sender.Lines);}
 [Fact]public void SpeakerNameSurvivesTheWhiteTextPass(){var merged=SpeakerMerge.WithSpeakerFrom(new Reading([new("We should keep moving.",new(.2,.8,.6,.9))]),new Reading([new("Jason: We should keep moving.",new(.1,.8,.6,.9))]));Assert.Equal("Jason: We should keep moving.",merged.Text);}
 [Fact]public void PunctuationAfterDialogueCannotCrashTheRereadGuard(){var guard=new RereadGuard();guard.Filter("We should keep moving right now.",0);Assert.Equal("---",guard.Filter("---",50));}
 [Fact]public async Task ExplicitCoalescingStillWorksWhenRequested(){long time=0;var sender=new Sender();var translator=new Translator();var pipeline=new SubtitlePipeline(new Reader("You can do","You can do","You can do that.","You can do that."),translator,sender,scheduler:ReadScheduler.Always(),clock:()=>time);DialogueReadingPolicy.Configure(pipeline,true,"dialogue");pipeline.HoldWithoutPacks=true;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));time=40;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));time=80;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));time=200;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));await pipeline.WaitForTranslationsAsync();Assert.Single(sender.Lines);Assert.Equal(1,translator.Calls);}
 [Fact]public async Task UnknownNamesCannotSuppressOrdinaryDialogue(){var sender=new Sender();var translator=new Translator();var pipeline=new SubtitlePipeline(new Reader("Get to the Dodo, Jay."),translator,sender);DialogueReadingPolicy.Configure(pipeline,true,"dialogue");pipeline.LooksMisread=_=>true;await pipeline.ProcessAsync(Frame.Blank(64,64),new(0,1,0,1));await pipeline.WaitForTranslationsAsync();Assert.False(pipeline.HoldWithoutPacks);Assert.Single(sender.Lines);}
}
